# A minimal agent loop (simplified) to show the architecture in code.
# Note how everything the model sees is one shared text context.

def run_agent(user_input, tools, memory):
    context = [
        {"role": "system", "content": SYSTEM_INSTRUCTIONS},
        *memory.load(),                 # trusted? maybe not
        {"role": "user", "content": user_input},
    ]

    while True:
        reply = llm.chat(context, tools=tools)

        if reply.tool_call:
            # Orchestrator runs the REAL function here.
            result = tools[reply.tool_call.name](**reply.tool_call.args)
            context.append({"role": "tool", "content": result})  # tool output re-enters context
        else:
            return reply.text            # final answer
